$u=verified_user();if(!contact_verified($u,'phone'))fail(403,'PHONE_VERIFICATION_REQUIRED','Verify your mobile number before booking.');$b=json_body();require_fields($b,['quoteId','customer']);if(!is_array($b['customer']))fail(422,'VALIDATION_ERROR','The request contains invalid data.',['customer'=>['Expected an object.']]);$key=idempotency_key();idempotent_replay($u['id'],'reservation-request',$key,$b);$customer=$b['customer'];$errors=[];foreach(['firstName','lastName'] as $f)if(trim((string)($customer[$f]??''))==='')$errors['customer.'.$f]=['Required.'];$email=trim((string)($customer['email']??''));$phone=trim((string)($customer['phone']??''));if($email===''&&$phone==='')$errors['customer.phone']=['Provide a contact phone or email.'];if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors['customer.email']=['Invalid email.'];if($errors)fail(422,'VALIDATION_ERROR','The request contains invalid data.',$errors);
db()->beginTransaction();$q=db()->prepare('SELECT * FROM quotes WHERE id=? FOR UPDATE');$q->execute([$b['quoteId']]);$quote=$q->fetch();if(!$quote||strtotime($quote['expires_at'])<=time())fail(409,'QUOTE_EXPIRED','Request a new quote.');if($quote['user_id']===null||$quote['user_id']!==$u['id'])fail(404,'NOT_FOUND','The requested quote was not found.');$used=db()->prepare('SELECT id FROM reservations WHERE quote_id=?');$used->execute([$quote['id']]);if($used->fetchColumn())fail(409,'QUOTE_CONSUMED','This quote has already been used.');$quoteData=decoded($quote['quote_json']);$partner=$quoteData['partnerId']??null;if(!$partner)fail(409,'SERVICE_UNAVAILABLE','No provider is assigned to this service.');if(!partner_operational((string)$partner))fail(409,'SERVICE_UNAVAILABLE','This provider is not available.');$table=$quote['service_type']==='driver'?'driver_services':'guide_services';$current=db()->prepare("SELECT service_json,owner_user_id FROM $table WHERE id=? AND status='published' FOR UPDATE");$current->execute([$quote['service_id']]);$service=$current->fetch();if(!$service||$service['owner_user_id']!==$partner||!partner_service_authorized((string)$partner,array_replace(decoded($service['service_json']),['id'=>$quote['service_id']]),$quote['service_type']))fail(409,'SERVICE_UNAVAILABLE','The current service or vehicle is not authorised.');$travelerSnapshot=require_traveler_profile($u,traveler_requirements(decoded($service['service_json'])));$id=uuid();$snapshot=['quote'=>$quoteData,'customer'=>$customer,'travelerDetails'=>$travelerSnapshot];db()->prepare("INSERT INTO reservations(id,customer_user_id,partner_user_id,quote_id,service_type,service_id,status,payment_status,snapshot_json,idempotency_key) VALUES(?,?,?,?,?,?,'requested','notCollected',?,?)")->execute([$id,$u['id'],$partner,$quote['id'],$quote['service_type'],$quote['service_id'],encoded($snapshot),$key]);$row=db()->prepare('SELECT * FROM reservations WHERE id=?');$row->execute([$id]);$response=reservation_